### Example 1: PostgreSQL Streaming Replication (Member Service)

**Scenario**: Member Service database experiencing read contention (95% connection pool utilization); need to scale read capacity.

**Solution**: Deploy 2 read replicas in same region (East US); route read queries to replicas via round-robin load balancing.

**Implementation**:

**Step 1: Create Read Replicas**:

```bash
# Create first replica
az postgres flexible-server replica create \

  --resource-group gainwell-prod \
  --name member-service-replica-1 \
  --source-server member-service-primary \
  --location eastus \
  --sku-name Standard_D4s_v3 \
  --tier GeneralPurpose \
  --storage-size 512

# Create second replica
az postgres flexible-server replica create \

  --resource-group gainwell-prod \
  --name member-service-replica-2 \
  --source-server member-service-primary \
  --location eastus \
  --sku-name Standard_D4s_v3 \
  --tier GeneralPurpose \
  --storage-size 512

# Verify replication status
az postgres flexible-server replica list \

  --resource-group gainwell-prod \
  --name member-service-primary --output table

# Output:
# Name                       Location    ReplicationRole    State    Lag
# member-service-replica-1   eastus      AsyncReplica       Active   42ms
# member-service-replica-2   eastus      AsyncReplica       Active   38ms
```

**Step 2: Configure Application**:

```csharp
// Program.cs (.NET 8 Minimal API)
var builder = WebApplication.CreateBuilder(args);

// Register database connection manager
builder.Services.AddSingleton<DatabaseConnectionManager>(sp =>
{
    var configuration = sp.GetRequiredService<IConfiguration>();
    var logger = sp.GetRequiredService<ILogger<DatabaseConnectionManager>>();

    var primaryConnectionString = configuration.GetConnectionString("Primary");
    var replicaConnectionStrings = configuration.GetSection("ConnectionStrings:Replicas").Get<List<string>>();

    return new DatabaseConnectionManager(primaryConnectionString, replicaConnectionStrings, logger);
});

// Register repositories
builder.Services.AddScoped<IMemberRepository, MemberRepository>();

var app = builder.Build();

app.MapGet("/api/members/{id:guid}", async (
    Guid id,
    IMemberRepository repository) =>
{
    var member = await repository.GetMemberByIdAsync(id);
    return member is not null ? Results.Ok(member) : Results.NotFound();
});

app.MapPost("/api/members", async (
    Member member,
    IMemberRepository repository) =>
{
    await repository.CreateMemberAsync(member);
    return Results.Created($"/api/members/{member.Id}", member);
});

app.Run();

// DatabaseConnectionManager.cs
public class DatabaseConnectionManager
{
    private readonly string _primaryConnectionString;
    private readonly List<string> _replicaConnectionStrings;
    private readonly ILogger<DatabaseConnectionManager> _logger;
    private int _replicaIndex = 0;
    private readonly object _lock = new();

    public DatabaseConnectionManager(
        string primaryConnectionString,
        List<string> replicaConnectionStrings,
        ILogger<DatabaseConnectionManager> logger)
    {
        _primaryConnectionString = primaryConnectionString;
        _replicaConnectionStrings = replicaConnectionStrings;
        _logger = logger;
    }

    public IDbConnection GetWriteConnection()
    {
        var connection = new NpgsqlConnection(_primaryConnectionString);
        connection.Open();
        _logger.LogDebug("Opened write connection to primary");
        return connection;
    }

    public IDbConnection GetReadConnection()
    {
        string replicaConnectionString;

        // Thread-safe round-robin selection
        lock (_lock)
        {
            replicaConnectionString = _replicaConnectionStrings[_replicaIndex];
            _replicaIndex = (_replicaIndex + 1) % _replicaConnectionStrings.Count;
        }

        try
        {
            var connection = new NpgsqlConnection(replicaConnectionString);
            connection.Open();
            _logger.LogDebug("Opened read connection to replica {Replica}", replicaConnectionString);
            return connection;
        }
        catch (NpgsqlException ex)
        {
            _logger.LogWarning(ex, "Failed to connect to replica. Falling back to primary.");
            return GetWriteConnection();
        }
    }
}

// MemberRepository.cs
public class MemberRepository : IMemberRepository
{
    private readonly DatabaseConnectionManager _connectionManager;

    public MemberRepository(DatabaseConnectionManager connectionManager)
    {
        _connectionManager = connectionManager;
    }

    public async Task<Member?> GetMemberByIdAsync(Guid memberId)
    {
        using var connection = _connectionManager.GetReadConnection();

        return await connection.QuerySingleOrDefaultAsync<Member>(
            @"SELECT id, name, date_of_birth, address, phone, email, created_at
              FROM members
              WHERE id = @MemberId",
            new { MemberId = memberId }
        );
    }

    public async Task CreateMemberAsync(Member member)
    {
        using var connection = _connectionManager.GetWriteConnection();

        await connection.ExecuteAsync(
            @"INSERT INTO members (id, name, date_of_birth, address, phone, email, created_at)
              VALUES (@Id, @Name, @DateOfBirth, @Address, @Phone, @Email, @CreatedAt)",
            member
        );
    }
}
```

**Step 3: Configuration**:

```json
// appsettings.json
{
  "ConnectionStrings": {
    "Primary": "Host=member-service-primary.postgres.database.azure.com;Database=members;Username=adminuser;Password=...;SslMode=Require;",
    "Replicas": [
      "Host=member-service-replica-1.postgres.database.azure.com;Database=members;Username=adminuser;Password=...;SslMode=Require;",
      "Host=member-service-replica-2.postgres.database.azure.com;Database=members;Username=adminuser;Password=...;SslMode=Require;"
    ]
  },
  "Logging": {
    "LogLevel": {
      "Default": "Information",
      "DatabaseConnectionManager": "Debug"
    }
  }
}
```

**Results**:

| Metric | Before (Primary Only) | After (Primary + 2 Replicas) | Improvement |
|--------|----------------------|------------------------------|-------------|
| **Connection Pool Utilization** | 95% | 35% | 2.7x reduction |
| **Read Query P95 Latency** | 850ms | 280ms | 3x faster |
| **Read Capacity** | 28K queries/min | 84K queries/min | 3x increase |
| **Primary CPU Utilization** | 85% | 42% | 51% reduction |

