### Example 2: CDC Pipeline for Provider Search (PostgreSQL → Elasticsearch)

**Scenario**: Provider directory search is slow (420ms P95 latency); need full-text search and geospatial queries ("cardiologist within 25 miles of San Francisco").

**Solution**: Replicate provider data to Elasticsearch using Change Data Capture (Debezium + Kafka); enable full-text and geospatial search.

**Implementation**:

**Step 1: Deploy Debezium Connector**:

```json
// debezium-connector-config.json
{
  "name": "provider-postgres-connector",
  "config": {
    "connector.class": "io.debezium.connector.postgresql.PostgresConnector",
    "database.hostname": "provider-service-primary.postgres.database.azure.com",
    "database.port": "5432",
    "database.user": "debezium_user",
    "database.password": "...",
    "database.dbname": "providers",
    "database.server.name": "provider-service",
    "table.include.list": "public.providers",
    "plugin.name": "pgoutput",
    "publication.name": "provider_publication",
    "slot.name": "provider_slot",
    "topic.prefix": "gainwell",
    "transforms": "route",
    "transforms.route.type": "org.apache.kafka.connect.transforms.RegexRouter",
    "transforms.route.regex": "([^.]+)\\.([^.]+)\\.([^.]+)",
  }
}

// Deploy connector to Kafka Connect
curl -X POST http://kafka-connect:8083/connectors \

  -H "Content-Type: application/json" \
  -d @debezium-connector-config.json
```

**Step 2: PostgreSQL Setup** (enable logical replication):

```sql
-- On provider-service-primary database

-- 1. Create replication user
CREATE ROLE debezium_user WITH LOGIN REPLICATION PASSWORD '...';
GRANT SELECT ON ALL TABLES IN SCHEMA public TO debezium_user;

-- 2. Create publication (defines what tables to replicate)
CREATE PUBLICATION provider_publication FOR TABLE providers;

-- 3. Create replication slot
SELECT pg_create_logical_replication_slot('provider_slot', 'pgoutput');

-- 4. Verify configuration
SELECT * FROM pg_replication_slots WHERE slot_name = 'provider_slot';

-- Output:
-- slot_name      | plugin   | slot_type | active | confirmed_flush_lsn
-- provider_slot  | pgoutput | logical   | t      | 0/24847744
```

**Step 3: Kafka Topic Configuration**:

```bash
# Create Kafka topic for provider changes
kafka-topics --create \

  --bootstrap-server kafka:9092 \
  --topic providers \
  --partitions 6 \
  --replication-factor 3 \
  --config retention.ms=604800000 \
  --config compression.type=gzip

# Topic: providers
# Partitions: 6 (for parallel processing)
# Retention: 7 days (for replay/recovery)
# Messages: Debezium change events (JSON)
```

**Step 4: Elasticsearch Consumer**:

```csharp
// ProviderSearchIndexer.cs (.NET Kafka Consumer → Elasticsearch)
public class ProviderSearchIndexer : BackgroundService
{
    private readonly IElasticClient _elasticClient;
    private readonly IConsumer<string, string> _kafkaConsumer;
    private readonly ILogger<ProviderSearchIndexer> _logger;

    public ProviderSearchIndexer(
        IElasticClient elasticClient,
        IConfiguration configuration,
        ILogger<ProviderSearchIndexer> logger)
    {
        _elasticClient = elasticClient;
        _logger = logger;

        var config = new ConsumerConfig
        {
            BootstrapServers = configuration["Kafka:BootstrapServers"],
            GroupId = "provider-search-indexer",
            AutoOffsetReset = AutoOffsetReset.Earliest,
            EnableAutoCommit = false
        };

        _kafkaConsumer = new ConsumerBuilder<string, string>(config).Build();
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        _kafkaConsumer.Subscribe("providers");

        while (!stoppingToken.IsCancellationRequested)
        {
            var consumeResult = _kafkaConsumer.Consume(stoppingToken);

            try
            {
                await ProcessChangeEventAsync(consumeResult.Message.Value);
                _kafkaConsumer.Commit(consumeResult);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to process change event. Offset: {Offset}",
                    consumeResult.Offset);
            }
        }
    }

    private async Task ProcessChangeEventAsync(string messageJson)
    {
        var changeEvent = JsonSerializer.Deserialize<DebeziumChangeEvent>(messageJson);

        switch (changeEvent.Payload.Op)
        {
            case "c": // Create
            case "u": // Update
            case "r": // Read (initial snapshot)
                await IndexProviderAsync(changeEvent.Payload.After);
                break;

            case "d": // Delete
                await DeleteProviderAsync(changeEvent.Payload.Before.Id);
                break;
        }
    }

    private async Task IndexProviderAsync(ProviderData provider)
    {
        var searchDocument = new ProviderSearchDocument
        {
            Id = provider.Id,
            Npi = provider.Npi,
            Name = provider.Name,
            Specialty = provider.Specialty,
            Location = new GeoLocation(provider.Latitude, provider.Longitude),
            Address = $"{provider.Address}, {provider.City}, {provider.State} {provider.Zip}",
            City = provider.City,
            State = provider.State,
            Zip = provider.Zip,
            Phone = provider.Phone,
            AcceptingNewPatients = provider.AcceptingNewPatients,
            Languages = provider.Languages?.Split(',').Select(l => l.Trim()).ToList(),
            SearchText = $"{provider.Name} {provider.Specialty} {provider.City} {provider.State}"
        };

        await _elasticClient.IndexDocumentAsync(searchDocument);
        _logger.LogInformation("Indexed provider {ProviderId} - {Name}", provider.Id, provider.Name);
    }

    private async Task DeleteProviderAsync(string providerId)
    {
        await _elasticClient.DeleteAsync<ProviderSearchDocument>(providerId);
        _logger.LogInformation("Deleted provider {ProviderId} from index", providerId);
    }
}

// ProviderSearchDocument.cs (Elasticsearch document model)
public class ProviderSearchDocument
{
    [Text(Name = "id")]
    public string Id { get; set; }

    [Keyword(Name = "npi")]
    public string Npi { get; set; }

    [Text(Name = "name", Analyzer = "standard")]
    public string Name { get; set; }

    [Keyword(Name = "specialty")]
    public string Specialty { get; set; }

    [GeoPoint(Name = "location")]
    public GeoLocation Location { get; set; }

    [Text(Name = "address")]
    public string Address { get; set; }

    [Keyword(Name = "city")]
    public string City { get; set; }

    [Keyword(Name = "state")]
    public string State { get; set; }

    [Keyword(Name = "zip")]
    public string Zip { get; set; }

    [Boolean(Name = "accepting_new_patients")]
    public bool AcceptingNewPatients { get; set; }

    [Text(Name = "search_text", Analyzer = "standard")]
    public string SearchText { get; set; }
}
```

**Step 5: Provider Search API**:

```csharp
// ProviderSearchService.cs
public class ProviderSearchService
{
    private readonly IElasticClient _elasticClient;

    public async Task<ProviderSearchResult> SearchProvidersAsync(ProviderSearchQuery query)
    {
        var searchResponse = await _elasticClient.SearchAsync<ProviderSearchDocument>(s => s
            .Index("providers")
            .Query(q => q
                .Bool(b => b
                    .Must(
                        // Full-text search on name, specialty
                        m => m.MultiMatch(mm => mm
                            .Query(query.SearchTerm)
                            .Fields(f => f
                                .Field(p => p.Name, boost: 2.0)
                                .Field(p => p.Specialty, boost: 1.5)
                                .Field(p => p.SearchText)
                            )
                            .Fuzziness(Fuzziness.Auto)
                        ),
                        // Geospatial filter (within radius)
                        m => m.GeoDistance(g => g
                            .Field(p => p.Location)
                            .Location(query.Latitude, query.Longitude)
                            .Distance($"{query.RadiusMiles}mi")
                        )
                    )
                    .Filter(
                        // Only active providers
                        f => f.Term(t => t.Field(p => p.AcceptingNewPatients).Value(true)),
                        // Specialty filter (if provided)
                        f => query.Specialty != null
                            ? f.Term(t => t.Field(p => p.Specialty).Value(query.Specialty))
                            : null
                    )
                )
            )
            .Size(query.PageSize)
            .From((query.Page - 1) * query.PageSize)
            .Sort(sort => sort
                .GeoDistance(g => g
                    .Field(p => p.Location)
                    .Location(query.Latitude, query.Longitude)
                    .Order(SortOrder.Ascending)
                )
            )
        );

        return new ProviderSearchResult
        {
            Providers = searchResponse.Documents.ToList(),
            TotalCount = searchResponse.Total,
            Page = query.Page,
            PageSize = query.PageSize
        };
    }
}

// API Endpoint (.NET Minimal API)
app.MapGet("/api/providers/search", async (
    [FromQuery] string searchTerm,
    [FromQuery] double latitude,
    [FromQuery] double longitude,
    [FromQuery] int radiusMiles = 25,
    [FromQuery] string? specialty = null,
    [FromQuery] int page = 1,
    [FromQuery] int pageSize = 20,
    ProviderSearchService searchService) =>
{
    var query = new ProviderSearchQuery
    {
        SearchTerm = searchTerm,
        Latitude = latitude,
        Longitude = longitude,
        RadiusMiles = radiusMiles,
        Specialty = specialty,
        Page = page,
        PageSize = pageSize
    };

    var result = await searchService.SearchProvidersAsync(query);
    return Results.Ok(result);
});

// Example API call:
// GET /api/providers/search?searchTerm=cardiologist&latitude=37.7749&longitude=-122.4194&radiusMiles=25
// Returns: Cardiologists within 25 miles of San Francisco, sorted by distance
```

**Results**:

| Metric | PostgreSQL (Before) | Elasticsearch (After CDC) | Improvement |
|--------|---------------------|---------------------------|-------------|
| **Search Latency (P95)** | 420ms | 70ms | 6x faster |
| **Full-Text Search** | ❌ Not supported | ✓ Fuzzy matching, stemming | New capability |
| **Geospatial Queries** | Slow (post-filter distance calculation) | ✓ Native geo queries | 10x faster |
| **Search Accuracy** | Exact match only | ✓ Relevance ranking, fuzzy search | Improved UX |
| **Replication Lag** | N/A | 2-4 seconds (CDC + Kafka + Elasticsearch) | Acceptable for search |

