```csharp
// DatabaseConnectionFactory.cs (with automatic retry)
public class DatabaseConnectionFactory
{
    private readonly string _connectionString;
    private readonly ILogger _logger;

    public IDbConnection CreateConnection()
    {
        var policy = Policy
            .Handle<NpgsqlException>()
            .WaitAndRetry(
                retryCount: 3,
                sleepDurationProvider: attempt => TimeSpan.FromSeconds(Math.Pow(2, attempt)),
                onRetry: (exception, timespan, retryCount, context) =>
                {
                    _logger.LogWarning(
                        "Database connection failed (attempt {RetryCount}): {Message}. Retrying in {Delay}s...",
                        retryCount, exception.Message, timespan.TotalSeconds
                    );
                }
            );

        return policy.Execute(() =>
        {
            var connection = new NpgsqlConnection(_connectionString);
            connection.Open();
            return connection;
        });
    }
}

// Application behavior during failover:
// 1. Primary fails (t=0s)
// 2. Existing connections fail ("Connection refused")
// 3. Retry #1 fails (t=1s) - Primary still offline
// 4. Retry #2 fails (t=3s) - DNS not yet updated
// 5. Retry #3 succeeds (t=7s) - DNS updated to new primary
// 6. Normal operations resume
// 7. Total user impact: 7-10s (brief error messages)
